    <script>
        (() => {
            const search = document.getElementById('guide-search');
            const sections = [...document.querySelectorAll('.guide-section')];
            const links = [...document.querySelectorAll('.guide-contents a')];
            const status = document.getElementById('search-status');
            let expandedBeforeSearch = null;
            search.addEventListener('input', () => {
                const query = search.value.trim().toLowerCase();
                if (query && expandedBeforeSearch === null) expandedBeforeSearch = [...document.querySelectorAll('details')].map(detail => [detail, detail.open]);
                let count = 0;
                sections.forEach(section => {
                    const matches = !query || `${section.textContent} ${section.dataset.search}`.toLowerCase().includes(query);
                    section.hidden = !matches;
                    if (matches) count++;
                    if (matches && query) section.querySelectorAll('details').forEach(detail => { detail.open = true; });
                });
                if (!query && expandedBeforeSearch) {
                    expandedBeforeSearch.forEach(([detail, open]) => { detail.open = open; });
                    expandedBeforeSearch = null;
                }
                document.getElementById('no-results').hidden = count > 0;
                status.textContent = query ? `${count} ${count === 1 ? 'section' : 'sections'} found.` : '';
            });
            document.getElementById('clear-search').addEventListener('click', () => {
                search.value = '';
                search.dispatchEvent(new Event('input'));
                search.focus();
            });
            links.forEach(link => link.addEventListener('click', () => {
                if (search.value) {
                    search.value = '';
                    search.dispatchEvent(new Event('input'));
                }
            }));
            const observer = new IntersectionObserver(entries => {
                entries.forEach(entry => {
                    if (entry.isIntersecting) links.forEach(link => link.classList.toggle('active', link.hash === `#${entry.target.id}`));
                });
            }, { rootMargin: '-15% 0px -65% 0px' });
            sections.forEach(section => observer.observe(section));
            document.getElementById('print-guide').addEventListener('click', () => {
                const states = [...document.querySelectorAll('details')].map(detail => [detail, detail.open]);
                const hiddenStates = sections.map(section => [section, section.hidden]);
                states.forEach(([detail]) => { detail.open = true; });
                sections.forEach(section => { section.hidden = false; });
                const restore = () => {
                    states.forEach(([detail, open]) => { detail.open = open; });
                    hiddenStates.forEach(([section, hidden]) => { section.hidden = hidden; });
                };
                window.addEventListener('afterprint', restore, { once: true });
                window.print();
            });
            const openLinkedSection = () => {
                const target = document.getElementById(window.location.hash.slice(1));
                if (target && target.tagName === 'DETAILS') target.open = true;
            };
            window.addEventListener('hashchange', openLinkedSection);
            openLinkedSection();
        })();
    </script>
</body>
</html>
